import re

from robot.api import logger

from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.utils.converters import create_dict_with_key_in_dict

TMGI_REGEXP = re.compile(r'(\d+:\d+:\d+)(\(\d+\))')
M1_IP_Multicast_Distribution_REGEXP = re.compile(r'(src:(\b(?:\w+[\.|:]+)+(?:\w+)\b)),(dst:(\b(?:\w+[\.|:]+)+(?:\w+)\b)),(teid:\d+)')


def parse_tmgi(value):
    """
    Parse value from "'TMGI' column of mbms_session_disp cmd

    :param value: column value as string
    :return: dict with tmgi and tmgi_dec

    Examlpe
    input:    1:244:09(21165200)
    output:   {"tmgi": 1:244:09, "dec_tmgi":21165200}
    """
    tmgi = re.search(TMGI_REGEXP, value)
    if tmgi:
        return {'tmgi': tmgi.group(1),
                'dec_tmgi': tmgi.group(2).strip('()')}
    else:
        return value


def parse_m1_ip_multicast_distribution(value):
    """
    Parse value from "'M1 IP Multicast Distribution' column of mbms_session_disp cmd

    :param value: column value as string
    :return: dict with src ip, dst ip and teid

    Example
    input:    src:10.0.1.1,dst:232.0.0.1,teid:1
    output:   {"src": "10.0.1.1", "dst": "232.0.0.1", "teid": 1}
    """
    m1_ip_multicast_distribution = re.search(M1_IP_Multicast_Distribution_REGEXP, value)
    if m1_ip_multicast_distribution:
        return {'src': m1_ip_multicast_distribution.group(2),
                'dst': m1_ip_multicast_distribution.group(4),
                'teid': m1_ip_multicast_distribution.group(5).split(':')[1]}
    else:
        return value


class MbmsSessionDispFailure(Exception):
    """
    Exception class for mbms_session_disp
    """
    pass


class MbmsSessionDisp(EgateCommandBase):
    """
    Parser for mbms_session_disp command output.
    """

    def __init__(self, **params):
        """

        :param params:
        """
        super(MbmsSessionDisp, self).__init__()
        self.command = 'mbms_session_disp'
        self.params = params
        self.executed_phrase = r'EGATE>\sMBMS\-GW.*?EGATE>\s*'
        self.fail_regexp = 'Error'
        self.to_execute = self.command
        self._build_command()
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def execute_and_parse(self, egate_id=0):
        """

        :return:
        """
        status, output = self.execute(egate_id=egate_id, command=self.to_execute)
        if status:
            parsed_output = self._parse_mbms_session_disp_output(output)
            logger.debug('{}: {} cmd parsed output:\n{}'.format(self.__class__.__name__, self.command, parsed_output))
            return parsed_output

    def _build_command(self):
        """
        Build laa_cell_counters command.
        :return: None
        """
        for param, value in list(self.params.items()):
            self.to_execute += ' {}={}'.format(param, value)

    def _parse_mbms_session_disp_output(self, cmd_output):
        """
        Parse mbms_disp command output
        :param cmd_output: output received from execution of mbms_session_disp command
        e.g.:

        MBMS-GW 1
        ======================================================================================================
        TMGI                M1 IP Multicast Distribution       DstIP    DstP   TrfTunIP/SrcIP  SAs  QCI  TSI
        ------------------------------------------------------------------------------------------------------
        1:244:09(21165200)  src:10.0.1.1,dst:232.0.0.1,teid:1  1.2.3.1  50001  1.2.3.1         1    1    -
        2:244:09(37942416)  src:10.0.1.1,dst:232.0.0.2,teid:1  1.2.3.1  50002  1.2.3.1         1    1    5
        ======================================================================================================

        EGATE>
        :return: dict with information about MBMS sessions with TMGIs as main keys
        e.g.:
        {
        ... '1:244:09': {'DstIP': '1.2.3.1',
        ...              'DstP': '50001',
        ...              'M1 IP Multicast Distribution': {'dst': '232.0.0.1',
        ...                                               'src': '10.0.1.1',
        ...                                               'teid': '1'},
        ...              'QCI': '1',
        ...              'SAs': '1',
        ...              'TMGI': {'dec_tmgi': '21165200',
        ...                       'tmgi': '1:244:09'},
        ...              'TSI': '-',
        ...              'TrfTunIP/SrcIP': '1.2.3.1'},
        ... '2:244:09': {'DstIP': '1.2.3.1',
        ...              'DstP': '50002',
        ...              'M1 IP Multicast Distribution': {'dst': '232.0.0.2',
        ...                                               'src': '10.0.1.1',
        ...                                               'teid': '1'},
        ...              'QCI': '1',
        ...              'SAs': '1',
        ...              'TMGI': {'dec_tmgi': '37942416',
        ...                       'tmgi': '2:244:09'},
        ...              'TSI': '5',
        ...              'TrfTunIP/SrcIP': '1.2.3.1'}
        }
        """
        if 'There is no MBMS-GW sessions for MBMS-GW' in cmd_output:
            return {}
        else:
            cmd_parser = EgateDispCommandsOutputParser(cmd_output)
            cmd_parser.parse_column_value_with_custom_function('TMGI', parse_tmgi)
            cmd_parser.parse_column_value_with_custom_function('M1 IP Multicast Distribution', parse_m1_ip_multicast_distribution)
            output = cmd_parser.get_list_of_output_parsed_lines()
            return create_dict_with_key_in_dict(key='TMGI',
                                                subkey='tmgi',
                                                list_of_output_parsed_lines=output)
